let audioCtx=null;function getAudioCtx(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext);if(audioCtx.state===`suspended`)audioCtx.resume();return audioCtx}function getSoundVolume(){try{const brut=localStorage.getItem(`kinetSoundVolume`);if(brut===null)return 1;const v=Number(brut);if(Number.isNaN(v))return 1;return Math.max(0,Math.min(100,v))/100}catch(e){return 1}}function setSoundVolume(pct){try{localStorage.setItem(`kinetSoundVolume`,String(pct))}catch(e){}}function getSoundEnabled(){try{return localStorage.getItem(`kinetSoundEnabled`)!==`0`}catch(e){return true}}function setSoundEnabled(on){try{localStorage.setItem(`kinetSoundEnabled`,on?`1`:`0`)}catch(e){}const toggle=document.getElementById(`soundToggle`);if(toggle)toggle.checked=on}const soundVolumeInput=document.getElementById(`soundVolume`);if(soundVolumeInput){soundVolumeInput.value=Math.round(getSoundVolume()*100);soundVolumeInput.addEventListener(`input`,e=>setSoundVolume(Number(e.target.value)))}document.getElementById(`soundToggle`).addEventListener(`change`,e=>{setSoundEnabled(e.target.checked);if(e.target.checked)playRouletteTick()});function playTone(freq,startGain,durationMs,type){if(!getSoundEnabled())return;try{const ctx=getAudioCtx();const osc=ctx.createOscillator();const gain=ctx.createGain();osc.type=type||`sine`;osc.frequency.value=freq;gain.gain.setValueAtTime(startGain*getSoundVolume(),ctx.currentTime);gain.gain.exponentialRampToValueAtTime(1e-4,ctx.currentTime+durationMs/1e3);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+durationMs/1e3)}catch(e){console.error(e)}}function playRouletteTick(){playTone(1400,.12,70,`square`)}function playRouletteWin(){if(!getSoundEnabled())return;[880,1108,1318].forEach((freq,i)=>{setTimeout(()=>playTone(freq,.14,220,`triangle`),i*90)})}function playCardFlip(){playTone(520,.05,110,`sine`)}const ACCORDS_RARETE={commun:[392],rare:[440,554],epique:[523,659,784],legendaire:[523,659,784,1047]};function playRarityReveal(rarete){if(!getSoundEnabled())return;const notes=ACCORDS_RARETE[rarete]||ACCORDS_RARETE.commun;const legendaire=rarete===`legendaire`;notes.forEach((freq,i)=>{setTimeout(()=>playTone(freq,legendaire?.14:.1,420,`triangle`),i*70)});if(legendaire){setTimeout(()=>playTone(2093,.05,600,`sine`),notes.length*70)}}function playChatbotBlip(){playTone(880,.05,90,`sine`)}function playSuccessChime(){if(!getSoundEnabled())return;[659,988].forEach((freq,i)=>{setTimeout(()=>playTone(freq,.1,260,`triangle`),i*110)})}function playDustChime(){playTone(330,.07,240,`sine`);setTimeout(()=>playTone(440,.05,180,`sine`),70)}function playPopChime(){playTone(1046,.08,120,`sine`)}function playDeleteTone(){if(!getSoundEnabled())return;playTone(440,.06,140,`sine`);setTimeout(()=>playTone(294,.05,160,`sine`),90)}const GAMME_NOTES=[330,370,415,494,587,659,784,880,1046];function playRatingTone(note){if(!getSoundEnabled())return;const n=Math.max(0,Math.min(5,Number(note)||0));const index=Math.round(n/5*(GAMME_NOTES.length-1));playTone(GAMME_NOTES[index],.1,300,`triangle`)}function playBoosterAmbient(dureeMs=3200){if(!getSoundEnabled())return;try{const ctx=getAudioCtx();const osc=ctx.createOscillator();const gain=ctx.createGain();osc.type=`sine`;osc.frequency.setValueAtTime(110,ctx.currentTime);osc.frequency.linearRampToValueAtTime(165,ctx.currentTime+dureeMs/1e3);gain.gain.setValueAtTime(1e-4,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.02*getSoundVolume()+1e-4,ctx.currentTime+.6);gain.gain.exponentialRampToValueAtTime(1e-4,ctx.currentTime+dureeMs/1e3);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+dureeMs/1e3)}catch(e){console.error(e)}}